file.content:
{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "telex/block-telex-countdown-timer",
	"version": "0.1.0",
	"title": "WordCamp Countdown Timer",
	"category": "widgets",
	"icon": "clock",
	"description": "A beautiful countdown timer block for WordCamp and future events with live preview, translucent cards, and full Gutenberg color support.",
	"example": {
		"attributes": {
			"eventTitle": "WordCamp Europe 2026",
			"targetDate": "2026-12-31T23:59:59",
			"completionMessage": "The event has started! 🎉"
		}
	},
	"attributes": {
		"eventTitle": {
			"type": "string",
			"default": "WordCamp 2026"
		},
		"targetDate": {
			"type": "string",
			"default": ""
		},
		"completionMessage": {
			"type": "string",
			"default": "The event has started! 🎉"
		}
	},
	"supports": {
		"html": false,
		"color": {
			"text": true,
			"background": true,
			"link": true
		},
		"spacing": {
			"margin": true,
			"padding": true
		},
		"typography": {
			"fontSize": true,
			"lineHeight": true
		},
		"align": [ "wide", "full" ]
	},
	"textdomain": "telex-countdown-timer",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"viewScript": "file:./view.js",
	"render": "file:./render.php"
}

/**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,
} );

/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, InspectorControls, RichText } from '@wordpress/block-editor';

import {
	PanelBody,
	DateTimePicker,
	TextControl,
} from '@wordpress/components';

import { useState, useEffect } from '@wordpress/element';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * Calculates the time remaining until a target date.
 *
 * @param {string} targetDate - ISO 8601 date string.
 * @return {{ days: number, hours: number, minutes: number, seconds: number, isComplete: boolean }} Time remaining.
 */
function getTimeRemaining( targetDate ) {
	if ( ! targetDate ) {
		return { days: 0, hours: 0, minutes: 0, seconds: 0, isComplete: false };
	}

	const total = new Date( targetDate ).getTime() - Date.now();

	if ( total <= 0 ) {
		return { days: 0, hours: 0, minutes: 0, seconds: 0, isComplete: true };
	}

	return {
		days: Math.floor( total / ( 1000 * 60 * 60 * 24 ) ),
		hours: Math.floor( ( total / ( 1000 * 60 * 60 ) ) % 24 ),
		minutes: Math.floor( ( total / ( 1000 * 60 ) ) % 60 ),
		seconds: Math.floor( ( total / 1000 ) % 60 ),
		isComplete: false,
	};
}

/**
 * Pads a number to two digits.
 *
 * @param {number} num - The number to pad.
 * @return {string} Zero-padded string.
 */
function padTwo( num ) {
	return String( num ).padStart( 2, '0' );
}

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @param {Object}   props               - Block props.
 * @param {Object}   props.attributes    - Block attributes.
 * @param {Function} props.setAttributes - Attribute setter.
 * @return {Element} Element to render.
 */
export default function Edit( { attributes, setAttributes } ) {
	const { eventTitle, targetDate, completionMessage } = attributes;
	const blockProps = useBlockProps( {
		className: 'telex-countdown-timer',
	} );

	const [ timeLeft, setTimeLeft ] = useState( () => getTimeRemaining( targetDate ) );

	useEffect( () => {
		setTimeLeft( getTimeRemaining( targetDate ) );

		if ( ! targetDate ) {
			return;
		}

		const interval = setInterval( () => {
			const remaining = getTimeRemaining( targetDate );
			setTimeLeft( remaining );
			if ( remaining.isComplete ) {
				clearInterval( interval );
			}
		}, 1000 );

		return () => clearInterval( interval );
	}, [ targetDate ] );

	const units = [
		{ value: timeLeft.days, label: __( 'Days', 'telex-countdown-timer' ) },
		{ value: timeLeft.hours, label: __( 'Hours', 'telex-countdown-timer' ) },
		{ value: timeLeft.minutes, label: __( 'Minutes', 'telex-countdown-timer' ) },
		{ value: timeLeft.seconds, label: __( 'Seconds', 'telex-countdown-timer' ) },
	];

	return (
		<>
			<InspectorControls>
				<PanelBody
					title={ __( 'Countdown Settings', 'telex-countdown-timer' ) }
					initialOpen={ true }
				>
					<div style={ { marginBottom: '16px' } }>
						<label
							style={ {
								display: 'block',
								marginBottom: '8px',
								fontWeight: 600,
								fontSize: '11px',
								textTransform: 'uppercase',
								letterSpacing: '0.5px',
							} }
						>
							{ __( 'Target Date & Time', 'telex-countdown-timer' ) }
						</label>
						<DateTimePicker
							currentDate={ targetDate || undefined }
							onChange={ ( newDate ) =>
								setAttributes( { targetDate: newDate } )
							}
							is12Hour={ true }
						/>
					</div>
					<TextControl
						__nextHasNoMarginBottom
						__next40pxDefaultSize
						label={ __( 'Completion Message', 'telex-countdown-timer' ) }
						help={ __( 'Displayed when the countdown reaches zero.', 'telex-countdown-timer' ) }
						value={ completionMessage }
						onChange={ ( value ) =>
							setAttributes( { completionMessage: value } )
						}
					/>
				</PanelBody>
			</InspectorControls>

			<div { ...blockProps }>
				<div className="telex-countdown-timer__inner">
					<RichText
						tagName="h2"
						className="telex-countdown-timer__title"
						value={ eventTitle }
						onChange={ ( value ) =>
							setAttributes( { eventTitle: value } )
						}
						placeholder={ __( 'Event Title…', 'telex-countdown-timer' ) }
						allowedFormats={ [
							'core/bold',
							'core/italic',
							'core/link',
						] }
					/>

					{ ! targetDate && (
						<p className="telex-countdown-timer__notice">
							{ __( 'Select a target date in the block settings sidebar.', 'telex-countdown-timer' ) }
						</p>
					) }

					{ targetDate && timeLeft.isComplete && (
						<p className="telex-countdown-timer__complete">
							{ completionMessage }
						</p>
					) }

					{ targetDate && ! timeLeft.isComplete && (
						<div
							className="telex-countdown-timer__grid"
							role="timer"
							aria-live="polite"
							aria-atomic="true"
							aria-label={ __( 'Countdown timer', 'telex-countdown-timer' ) }
						>
							{ units.map( ( unit ) => (
								<div
									className="telex-countdown-timer__card"
									key={ unit.label }
								>
									<span className="telex-countdown-timer__value">
										{ padTwo( unit.value ) }
									</span>
									<span className="telex-countdown-timer__label">
										{ unit.label }
									</span>
								</div>
							) ) }
						</div>
					) }
				</div>
			</div>
		</>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 */

.wp-block-telex-block-telex-countdown-timer {
	--countdown-accent: #f56530;
	--countdown-text: #00595d;
	--countdown-bg: #fff9ef;

	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
	color: var(--wp--custom--color--text, var(--countdown-text));
	background: var(--wp--custom--color--background, var(--countdown-bg));
	border-radius: 16px;
	overflow: hidden;
	position: relative;
}

.wp-block-telex-block-telex-countdown-timer.has-text-color {
	--countdown-text: currentColor;
}

.wp-block-telex-block-telex-countdown-timer.has-background {
	--countdown-bg: currentColor;
}

.wp-block-telex-block-telex-countdown-timer.has-link-color {
	--countdown-accent: var(--wp--style--block--link-color, #f56530);
}

.telex-countdown-timer__inner {
	padding: 2.5rem 2rem;
	text-align: center;
	position: relative;
	z-index: 1;
}

.telex-countdown-timer__title {
	font-size: clamp(1.25rem, 3vw, 2rem);
	font-weight: 700;
	margin: 0 0 0.25rem;
	letter-spacing: -0.02em;
	line-height: 1.2;
	color: inherit;

	a {
		color: var(--countdown-accent);
		text-decoration: underline;
		text-decoration-thickness: 2px;
		text-underline-offset: 3px;

		&:hover,
		&:focus {
			opacity: 0.85;
		}
	}
}

.telex-countdown-timer__notice {
	font-size: 0.95rem;
	opacity: 0.7;
	margin: 1.5rem 0 0;
	font-style: italic;
}

.telex-countdown-timer__complete {
	font-size: clamp(1.1rem, 2.5vw, 1.5rem);
	font-weight: 600;
	margin: 1.5rem 0 0;
	color: var(--countdown-accent);
	animation: countdown-fade-in 0.6s ease-out;
}

.telex-countdown-timer__grid {
	display: grid;
	grid-template-columns: repeat(4, 1fr);
	gap: clamp(0.5rem, 2vw, 1rem);
	margin-top: 1.75rem;
	max-width: 560px;
	margin-inline: auto;
}

.telex-countdown-timer__card {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	padding: clamp(0.75rem, 2vw, 1.25rem) clamp(0.5rem, 1.5vw, 1rem);
	border-radius: 12px;
	background: color-mix(in srgb, var(--countdown-accent) 10%, transparent);
	border: 1px solid color-mix(in srgb, var(--countdown-accent) 20%, transparent);
	backdrop-filter: blur(8px);
	transition: transform 0.2s ease, box-shadow 0.2s ease;

	&:hover {
		transform: translateY(-2px);
		box-shadow: 0 6px 20px color-mix(in srgb, var(--countdown-accent) 15%, transparent);
	}
}

.telex-countdown-timer__value {
	font-size: clamp(1.75rem, 5vw, 3rem);
	font-weight: 800;
	line-height: 1;
	letter-spacing: -0.03em;
	color: var(--countdown-accent);
	font-variant-numeric: tabular-nums;
	font-feature-settings: "tnum";
}

.telex-countdown-timer__label {
	font-size: clamp(0.6rem, 1.5vw, 0.8rem);
	font-weight: 600;
	text-transform: uppercase;
	letter-spacing: 0.1em;
	margin-top: 0.35rem;
	opacity: 0.7;
	color: inherit;
}

@keyframes countdown-fade-in {
	from {
		opacity: 0;
		transform: translateY(8px);
	}

	to {
		opacity: 1;
		transform: translateY(0);
	}
}

@media (max-width: 480px) {
	.telex-countdown-timer__grid {
		grid-template-columns: repeat(2, 1fr);
	}

	.telex-countdown-timer__inner {
		padding: 1.75rem 1.25rem;
	}
}

/**
 * The following styles get applied inside the editor only.
 */

.wp-block-telex-block-telex-countdown-timer {
	.telex-countdown-timer__title {
		&:focus {
			outline: 2px solid var(--countdown-accent);
			outline-offset: 2px;
			border-radius: 4px;
		}
	}

	.telex-countdown-timer__notice {
		padding: 1rem;
		background: color-mix(in srgb, var(--countdown-accent) 8%, transparent);
		border-radius: 8px;
		border: 1px dashed color-mix(in srgb, var(--countdown-accent) 30%, transparent);
	}
}

/**
 * Frontend countdown timer logic.
 * Each block instance independently manages its own interval.
 * Cleans up intervals when elements are removed from the DOM.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-metadata/#view-script
 */

/**
 * Pads a number with leading zeros to two digits.
 *
 * @param {number} num - The number to pad.
 * @return {string} The zero-padded number string.
 */
function padTwo( num ) {
	return String( num ).padStart( 2, '0' );
}

/**
 * Calculates the time remaining until a target timestamp.
 *
 * @param {number} targetTimestamp - Target time in milliseconds.
 * @return {{ days: number, hours: number, minutes: number, seconds: number, isComplete: boolean }} Remaining time.
 */
function getTimeRemaining( targetTimestamp ) {
	const total = targetTimestamp - Date.now();

	if ( total <= 0 ) {
		return { days: 0, hours: 0, minutes: 0, seconds: 0, isComplete: true };
	}

	return {
		days: Math.floor( total / ( 1000 * 60 * 60 * 24 ) ),
		hours: Math.floor( ( total / ( 1000 * 60 * 60 ) ) % 24 ),
		minutes: Math.floor( ( total / ( 1000 * 60 ) ) % 60 ),
		seconds: Math.floor( ( total / 1000 ) % 60 ),
		isComplete: false,
	};
}

/**
 * Initializes a single countdown block instance.
 *
 * @param {HTMLElement} block - The block wrapper element.
 * @return {number|null} The interval ID, or null if no interval was started.
 */
function initCountdown( block ) {
	const targetDateStr = block.dataset.targetDate;

	if ( ! targetDateStr ) {
		return null;
	}

	const targetTimestamp = new Date( targetDateStr ).getTime();

	if ( isNaN( targetTimestamp ) ) {
		return null;
	}

	const grid = block.querySelector( '.telex-countdown-timer__grid' );
	const completeEl = block.querySelector( '.telex-countdown-timer__complete' );
	const values = block.querySelectorAll( '.telex-countdown-timer__value' );

	if ( ! grid || values.length < 4 ) {
		return null;
	}

	/**
	 * Updates the countdown display.
	 */
	function tick() {
		const remaining = getTimeRemaining( targetTimestamp );

		values[ 0 ].textContent = padTwo( remaining.days );
		values[ 1 ].textContent = padTwo( remaining.hours );
		values[ 2 ].textContent = padTwo( remaining.minutes );
		values[ 3 ].textContent = padTwo( remaining.seconds );

		if ( remaining.isComplete ) {
			clearInterval( intervalId );
			grid.setAttribute( 'aria-hidden', 'true' );
			grid.style.display = 'none';

			if ( completeEl ) {
				completeEl.hidden = false;
				completeEl.removeAttribute( 'aria-hidden' );
			}
		}
	}

	// Initial tick.
	tick();

	// Check if already complete before starting interval.
	const initial = getTimeRemaining( targetTimestamp );
	if ( initial.isComplete ) {
		return null;
	}

	const intervalId = setInterval( tick, 1000 );
	return intervalId;
}

document.addEventListener( 'DOMContentLoaded', function () {
	const blocks = document.querySelectorAll( '.wp-block-telex-block-telex-countdown-timer' );

	/** @type {Map<HTMLElement, number>} */
	const intervals = new Map();

	blocks.forEach( function ( block ) {
		const intervalId = initCountdown( block );
		if ( intervalId !== null ) {
			intervals.set( block, intervalId );
		}
	} );

	// Clean up intervals when blocks are removed from the DOM.
	if ( intervals.size > 0 && typeof MutationObserver !== 'undefined' ) {
		const observer = new MutationObserver( function ( mutations ) {
			mutations.forEach( function ( mutation ) {
				mutation.removedNodes.forEach( function ( node ) {
					if ( node.nodeType !== Node.ELEMENT_NODE ) {
						return;
					}

					intervals.forEach( function ( id, el ) {
						if ( node === el || node.contains( el ) ) {
							clearInterval( id );
							intervals.delete( el );
						}
					} );
				} );
			} );

			if ( intervals.size === 0 ) {
				observer.disconnect();
			}
		} );

		observer.observe( document.body, {
			childList: true,
			subtree: true,
		} );
	}
} );

{
	"name": "telex-countdown-timer",
	"version": "0.1.0",
	"description": "A beautiful countdown timer block for WordCamp and future events with live preview, translucent cards, and full Gutenberg color support.",
	"author": "WordPress Telex",
	"license": "GPL-2.0-or-later",
	"main": "build/index.js",
	"scripts": {
		"build": "wp-scripts build",
		"format": "wp-scripts format",
		"lint:css": "wp-scripts lint-style",
		"lint:js": "wp-scripts lint-js",
		"packages-update": "wp-scripts packages-update",
		"plugin-zip": "wp-scripts plugin-zip",
		"start": "wp-scripts start"
	},
	"devDependencies": {
		"@wordpress/scripts": "^30.15.0"
	}
}
